# Generated from SymPy outputs (reference commit 86150a81): the doit calls
# made by SymPy's test_sums_products.py and test_gosper.py, each evaluated
# afresh. Only inputs on which the port agrees with SymPy are listed.

test_that("Sum.doit matches SymPy on the calls of its test files", {
  skip_on_cran()
  chk <- function(s, deep, loc, want) {
    e <- sympify(s, locals = loc)
    v <- doit(e, deep = deep)
    expect_equal(sstr(v), want, label = s)
  }
  chk("Sum(n*Integral(a**2, a), (n, 0, 2))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), a = Symbol("a")), "a^3")
  chk("Sum(n*Integral(a**2, a), (n, 0, 2))", FALSE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), a = Symbol("a")), "3*Integral(a^2, a)")
  chk("Sum(2, (z, 1, n + 1), (y, x + 1, n), (x, 1, n))", TRUE, list(x = Symbol("x"), z = Symbol("z"), n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), y = Symbol("y")), "n*(2*n^2 + 2*n) + (-2*n - 2)*(n^2/2 + n/2)")
  chk("Sum(KroneckerDelta(x, y), (x, -oo, oo))", TRUE, list(y = Symbol("y"), x = Symbol("x")), "Piecewise((1, (y > -oo) & (y < oo)), (0, True))")
  chk("Sum(KroneckerDelta(m, n), (m, -oo, oo))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), m = Symbol("m")), "1")
  chk("Sum(m*KroneckerDelta(x, y), (x, -oo, oo))", TRUE, list(y = Symbol("y"), x = Symbol("x"), m = Symbol("m")), "Piecewise((m, (y > -oo) & (y < oo)), (0, True))")
  chk("Sum(x*KroneckerDelta(m, n), (m, -oo, oo))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), x = Symbol("x"), m = Symbol("m")), "x")
  chk("Sum(KroneckerDelta(m, n), (m, 1, 3), (n, 1, 3))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), m = Symbol("m")), "3")
  chk("Sum(KroneckerDelta(k, m), (m, 1, 3), (n, 1, 3))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), k = Symbol("k"), m = Symbol("m")), "3*Piecewise((1, (k >= 1) & (k <= 3)), (0, True))")
  chk("Sum(f(n)*Sum(KroneckerDelta(m, n), (m, 0, oo)), (n, 1, 3))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), m = Symbol("m")), "f(1) + f(2) + f(3)")
  chk("Sum(f(n)*Sum(KroneckerDelta(m, n), (m, 0, oo)), (n, 1, oo))", TRUE, list(n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE), m = Symbol("m")), "Sum(f(n), (n, 1, oo))")
  chk("Sum(Piecewise((1, (N >= n) & (n >= 1)), (0, True)), (n, 1, N))", TRUE, list(N = Symbol("N", complex = TRUE, extended_nonnegative = TRUE, extended_positive = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, nonnegative = TRUE, nonzero = TRUE, positive = TRUE, rational = TRUE, real = TRUE), n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE)), "Sum(Piecewise((1, N >= n), (0, True)), (n, 1, N))")
  chk("Sum(n**(-2*s), (n, 1, oo))", FALSE, list(s = Symbol("s"), n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE)), "Piecewise((zeta(2*s), re(s) > 1/2), (Sum(n^(-2*s), (n, 1, oo)), True))")
  chk("Sum((n + 1)**(-s), (n, 0, oo))", FALSE, list(s = Symbol("s"), n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE)), "Piecewise((zeta(s), re(s) > 1), (Sum((n + 1)^(-s), (n, 0, oo)), True))")
  chk("Sum((n + q)**(-s), (n, 0, oo))", FALSE, list(q = Symbol("q"), s = Symbol("s"), n = Symbol("n", complex = TRUE, extended_real = TRUE, finite = TRUE, integer = TRUE, rational = TRUE, real = TRUE)), "Piecewise((zeta(s, q), (re(s) > 1) & ~Contains(-q, Naturals0)), (Sum((n + q)^(-s), (n, 0, oo)), True))")
